"""Add a leakage-safe 90-day reconstructed V4 history using all prior history.

The 90-day window controls only what is displayed. Historical V4 models use
expanding training windows over all eligible V4 history available before each
walk-forward validation fold, with the existing five-session purge. The
reconstruction remains separate from genuine paper-trading state and journals.
"""

from pathlib import Path

APP = Path("webapp/app.py")
TEMPLATE = Path("webapp/templates/index.html")
SERVICE = Path("webapp/services/v4_reconstructed_history_service.py")
RUNNER = Path("ml/run_v4_90d_reconstruction.py")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f"Cannot apply {label}: expected text not found")
    print(f"[APPLY] {label}")
    return text.replace(old, new, 1)


def main() -> None:
    SERVICE.write_text('''"""Read-only loader for reconstructed V4 90-day equity history."""\n\nimport json\nfrom pathlib import Path\n\nPATH = Path("data/paper_trading/v4_reconstructed_90d.json")\n\ndef get_v4_reconstructed_90d_history():\n    if not PATH.exists():\n        return []\n    try:\n        payload = json.loads(PATH.read_text(encoding="utf-8"))\n    except (OSError, json.JSONDecodeError):\n        return []\n    return [\n        {**row, "reconstructed": True, "history_type": "RECONSTRUCTED_WALK_FORWARD_90D"}\n        for row in payload.get("history", [])\n        if row.get("timestamp") is not None and row.get("equity") is not None\n    ]\n''', encoding="utf-8")
    print("[APPLY] V4 reconstructed all-history reader")

    RUNNER.write_text('''"""Build the display-only 90-day V4 reconstructed portfolio curve.\n\nThe 90-day period is only the chart window. Model training is NOT limited to\n90 days. The existing V4 expanding-window walk-forward generator uses all\neligible historical V4 observations available before each fold and keeps the\nexisting five-trading-session purge between training and validation.\n\nA model decision made after a completed trading session is applied at the next\ntrading session open. No future observations are used to create an earlier\ndecision. This script never changes the genuine paper portfolio or journal.\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom ml.backtest_portfolio_v4 import load_v4_data, generate_walk_forward_signals\nfrom ml.train_model_v4 import PURGE_GAP\n\nimport sys\nsys.path.append("data-ingestion")\nfrom symbols import SYMBOLS\n\nSTARTING_EQUITY = 100_000.0\nCORE_WEIGHT = 0.60\nV4_POSITION_WEIGHT = 0.08\nENTRY_COST = 0.001\nEXIT_COST = 0.001\nDISPLAY_DAYS = 90\nOUT = Path("data/paper_trading/v4_reconstructed_90d.json")\nSTATE = Path("data/paper_trading/portfolio.json")\n\n\ndef as_utc(value):\n    ts = pd.Timestamp(value)\n    return ts.tz_convert("UTC") if ts.tzinfo else ts.tz_localize("UTC")\n\n\ndef load_prices(symbols):\n    frames = {}\n    for symbol in symbols:\n        p = Path(f"data/features/stocks/{symbol}/{symbol}_features.parquet")\n        if not p.exists():\n            raise FileNotFoundError(f"Missing feature history: {p}")\n        df = pd.read_parquet(p, columns=["timestamp_utc", "open", "close"])\n        df["timestamp_utc"] = pd.to_datetime(df["timestamp_utc"], utc=True)\n        frames[symbol] = df.set_index("timestamp_utc").sort_index()\n    return frames\n\n\ndef price(frames, symbol, timestamp, field):\n    try:\n        value = float(frames[symbol].at[pd.Timestamp(timestamp), field])\n    except Exception:\n        return None\n    return value if np.isfinite(value) and value > 0 else None\n\n\ndef main():\n    X, y, model_symbols, timestamps, _ = load_v4_data()\n    all_model_dates = sorted({as_utc(x) for x in timestamps.tolist()})\n    if not all_model_dates:\n        raise RuntimeError("V4 historical dataset contains no trading dates")\n\n    training_history_start = all_model_dates[0]\n    training_history_end = all_model_dates[-1]\n\n    # Important: this call sees the COMPLETE historical V4 dataset. Its\n    # expanding folds train on every eligible earlier observation, rather than\n    # restricting training to the 90-day display period.\n    signals, unique_dates_raw = generate_walk_forward_signals(\n        X, y, model_symbols, timestamps\n    )\n    unique_dates = [as_utc(x) for x in unique_dates_raw]\n\n    by_signal = {}\n    for row in signals:\n        ts = as_utc(row["signal_timestamp"])\n        by_signal.setdefault(ts, []).append(row)\n    for ts, rows in by_signal.items():\n        by_signal[ts] = sorted(rows, key=lambda r: r["probability"], reverse=True)[:5]\n\n    frames = load_prices(list(dict.fromkeys([*SYMBOLS, "SPY"])))\n\n    paper_start = None\n    if STATE.exists():\n        try:\n            state = json.loads(STATE.read_text(encoding="utf-8"))\n            raw = state.get("strategy_started_at") or state.get("created_at")\n            if raw:\n                paper_start = as_utc(raw)\n        except Exception:\n            paper_start = None\n\n    latest_display_anchor = min(\n        training_history_end,\n        paper_start if paper_start is not None else training_history_end,\n    )\n    requested_start = latest_display_anchor - pd.Timedelta(days=DISPLAY_DAYS)\n    eligible_dates = [\n        d for d in unique_dates\n        if d >= requested_start and (paper_start is None or d < paper_start)\n    ]\n    if len(eligible_dates) < 2:\n        raise RuntimeError("Not enough pre-paper dates in the requested 90-day chart window")\n\n    previous = {unique_dates[i]: unique_dates[i - 1] for i in range(1, len(unique_dates))}\n    first = None\n    first_target = None\n    for session in eligible_dates:\n        signal_session = previous.get(session)\n        ranked = by_signal.get(signal_session, [])\n        target = [row["symbol"] for row in ranked][:5]\n        needed = ["SPY", *target]\n        if len(target) == 5 and all(price(frames, s, session, "open") for s in needed):\n            first, first_target = session, target\n            break\n    if first is None:\n        raise RuntimeError("Could not find a valid reconstructed start session")\n\n    cash = STARTING_EQUITY\n    positions = {}\n    trade_actions = 0\n    modeled_friction = 0.0\n\n    def buy(symbol, sleeve, budget, session):\n        nonlocal cash, trade_actions, modeled_friction\n        market_price = price(frames, symbol, session, "open")\n        if market_price is None or budget <= 0:\n            return\n        effective_price = market_price * (1.0 + ENTRY_COST)\n        shares = budget / effective_price\n        used = shares * effective_price\n        fee = shares * market_price * ENTRY_COST\n        cash -= used\n        modeled_friction += fee\n        trade_actions += 1\n        positions[symbol] = {"shares": shares, "sleeve": sleeve}\n\n    buy("SPY", "core", STARTING_EQUITY * CORE_WEIGHT, first)\n    for symbol in first_target:\n        buy(symbol, "v4", STARTING_EQUITY * V4_POSITION_WEIGHT, first)\n\n    history = []\n    for session in [d for d in eligible_dates if d >= first]:\n        signal_session = previous.get(session)\n        ranked = by_signal.get(signal_session, [])\n        target = [row["symbol"] for row in ranked][:5]\n\n        if len(target) == 5 and session != first:\n            current_v4 = {s for s, p in positions.items() if p["sleeve"] == "v4"}\n            target_set = set(target)\n\n            for symbol in sorted(current_v4 - target_set):\n                market_price = price(frames, symbol, session, "open")\n                if market_price is None:\n                    continue\n                pos = positions.pop(symbol)\n                gross = pos["shares"] * market_price\n                fee = gross * EXIT_COST\n                cash += gross - fee\n                modeled_friction += fee\n                trade_actions += 1\n\n            open_equity = cash\n            for symbol, pos in positions.items():\n                market_price = price(frames, symbol, session, "open")\n                if market_price is not None:\n                    open_equity += pos["shares"] * market_price\n\n            current_v4 = {s for s, p in positions.items() if p["sleeve"] == "v4"}\n            for symbol in target:\n                if symbol in current_v4:\n                    continue\n                budget = min(open_equity * V4_POSITION_WEIGHT, cash)\n                buy(symbol, "v4", budget, session)\n\n        close_equity = cash\n        valid = True\n        for symbol, pos in positions.items():\n            close_price = price(frames, symbol, session, "close")\n            if close_price is None:\n                valid = False\n                break\n            close_equity += pos["shares"] * close_price\n        if not valid:\n            continue\n\n        history.append({\n            "timestamp": session.isoformat(),\n            "equity": round(close_equity, 2),\n            "reconstructed": True,\n            "history_type": "RECONSTRUCTED_WALK_FORWARD_90D",\n            "top_five": target if len(target) == 5 else None,\n        })\n\n    if not history:\n        raise RuntimeError("No reconstructed equity observations produced")\n\n    payload = {\n        "history_type": "RECONSTRUCTED_WALK_FORWARD_90D",\n        "simulation_only": True,\n        "genuine_paper_journal_modified": False,\n        "brokerage_orders": False,\n        "display_window_calendar_days": DISPLAY_DAYS,\n        "model_training_window": "EXPANDING_ALL_ELIGIBLE_PRIOR_HISTORY",\n        "training_history_start": training_history_start.isoformat(),\n        "training_history_end": training_history_end.isoformat(),\n        "purge_gap_trading_sessions": int(PURGE_GAP),\n        "reconstruction_start": history[0]["timestamp"],\n        "reconstruction_end": history[-1]["timestamp"],\n        "observations": len(history),\n        "starting_equity": STARTING_EQUITY,\n        "ending_equity": history[-1]["equity"],\n        "total_return_pct": round((history[-1]["equity"] / STARTING_EQUITY - 1.0) * 100.0, 4),\n        "trade_actions": trade_actions,\n        "modeled_friction": round(modeled_friction, 2),\n        "method": (\n            "90-day display window only; expanding V4 walk-forward models train on all eligible "\n            "prior history with a five-session purge; completed-session decisions are applied at "\n            "the next trading-session open; 60% permanent SPY core; five 8% V4 positions; "\n            "10 bps entry/exit friction"\n        ),\n        "paper_start_boundary": paper_start.isoformat() if paper_start is not None else None,\n        "history": history,\n    }\n\n    OUT.parent.mkdir(parents=True, exist_ok=True)\n    OUT.write_text(json.dumps(payload, indent=2), encoding="utf-8")\n\n    print("V4 90-DAY ALL-HISTORY RECONSTRUCTION")\n    print("=" * 78)\n    print("Historical training data:", payload["training_history_start"], "->", payload["training_history_end"])\n    print("Training policy:", payload["model_training_window"])\n    print("Purge gap:", payload["purge_gap_trading_sessions"], "trading sessions")\n    print("Displayed reconstruction:", payload["reconstruction_start"], "->", payload["reconstruction_end"])\n    print("Observations:", payload["observations"])\n    print("Ending equity:", f'${payload["ending_equity"]:,.2f}')\n    print("Return:", f'{payload["total_return_pct"]:+.4f}%')\n    print("Trade actions:", payload["trade_actions"])\n    print("Modeled friction:", f'${payload["modeled_friction"]:,.2f}')\n    print("Paper boundary:", payload["paper_start_boundary"])\n    print()\n    print("The 90-day period limits DISPLAY only; model training uses all eligible prior history.")\n    print("RECONSTRUCTED/SIMULATION ONLY. Genuine paper journal unchanged. No brokerage orders.")\n\nif __name__ == "__main__":\n    main()\n''', encoding="utf-8")
    print("[APPLY] V4 90-day expanding all-history reconstruction runner")

    text = APP.read_text(encoding="utf-8")
    import_line = 'from webapp.services.v4_realtime_equity_journal_service import get_v4_realtime_equity_history  # noqa: E402\n'
    new_import = import_line + 'from webapp.services.v4_reconstructed_history_service import get_v4_reconstructed_90d_history  # noqa: E402\n'
    if 'get_v4_reconstructed_90d_history' not in text:
        text = replace_once(text, import_line, new_import, "app import for reconstructed all-history curve")

    old_history = '    history = list(forward.get("equity_history", []))\n    history.extend(get_v4_realtime_equity_history())\n    history.sort(key=lambda row: str(row.get("timestamp") or ""))\n    chart_history = [\n        {\n            "timestamp": forward.get("start_timestamp"),\n'
    new_history = '    reconstructed = get_v4_reconstructed_90d_history()\n    history = list(reconstructed)\n    history.extend(forward.get("equity_history", []))\n    history.extend(get_v4_realtime_equity_history())\n    history.sort(key=lambda row: str(row.get("timestamp") or ""))\n    reconstructed_start = reconstructed[0].get("timestamp") if reconstructed else forward.get("start_timestamp")\n    chart_history = [\n        {\n            "timestamp": reconstructed_start,\n'
    if 'reconstructed = get_v4_reconstructed_90d_history()' not in text:
        text = replace_once(text, old_history, new_history, "prepend all-history reconstruction to V4 chart")
    APP.write_text(text, encoding="utf-8")

    text = TEMPLATE.read_text(encoding="utf-8")
    old_desc = "Recorded V4 journal equity plus a live read-only current mark-to-market point."
    new_desc = "90-day reconstructed walk-forward V4 history using all eligible prior training data, followed by actual paper-journal equity and live read-only marks."
    if old_desc in text:
        text = text.replace(old_desc, new_desc, 1)
        print("[APPLY] V4 chart all-history description")
    TEMPLATE.write_text(text, encoding="utf-8")

    print()
    print("V4 90-day all-history reconstruction patch complete.")
    print("The 90-day range is display-only; historical model training uses all eligible prior V4 history.")
    print("No genuine paper history is backdated or modified.")


if __name__ == "__main__":
    main()
